package main

//go:generate go tool sqlc generate -f sqlc.yaml

// The two transaction entry points of docs/designs/fleet-standard.md S3, over Store.txLocks: Read and Write, typed
// queries through q.db() (package db, generated by sqlc from queries/<area>.sql) and effects after commit through
// afterCommit. readOnce/writeOnce serve work_kit.go's single-attempt cohort and retry-accounting steps.

import (
	"context"
	"errors"

	"github.com/jackc/pgx/v5"

	"fleet/coordinator/db"
)

// Read runs fn in a read-only repeatable-read snapshot as person q (its scope), or as the coordinator's background work
// when q is nil. Inside a transaction already open for q (an operation's), fn runs in it.
func (s *Store) Read(ctx context.Context, q *Request, fn func(q *Request) error) error {
	return s.read(ctx, q, true, fn)
}

// Write runs fn in a write transaction holding locks, the entity keys fn writes (lockRank: GLOBAL only by name, where the
// write is truly global; none takes no advisory lock). Inside a write transaction already open for q, it acquires the
// locks there, in canonical order after those already held, and runs fn in it; inside a read transaction it fails.
func (s *Store) Write(ctx context.Context, q *Request, locks []string, fn func(q *Request) error) error {
	return s.write(ctx, q, locks, true, fn)
}

// readOnce runs a single-attempt read transaction without Store-level retry (for work_kit.go).
func (s *Store) readOnce(ctx context.Context, q *Request, fn func(q *Request) error) error {
	return s.read(ctx, q, false, fn)
}

// writeOnce runs a single-attempt write transaction without Store-level retry (for work_kit.go).
func (s *Store) writeOnce(ctx context.Context, q *Request, locks []string, fn func(q *Request) error) error {
	return s.write(ctx, q, locks, false, fn)
}

func (s *Store) read(ctx context.Context, q *Request, retry bool, fn func(q *Request) error) error {
	if q != nil && q.tx != nil {
		return fn(q)
	}
	return s.run(ctx, q, false, nil, retry, fn)
}

func (s *Store) write(ctx context.Context, q *Request, locks []string, retry bool, fn func(q *Request) error) error {
	if q != nil && q.tx != nil {
		if !txWrites(q.tx) {
			return errors.New("store.Write inside a read transaction")
		}
		if err := acquireTxLocks(ctx, q.tx, locks...); err != nil {
			return err
		}
		return fn(q)
	}
	return s.run(ctx, q, true, locks, retry, fn)
}

func (s *Store) appOf() *App {
	if s.app != nil {
		return s.app
	}
	return runningApp
}

func (s *Store) run(ctx context.Context, q *Request, write bool, locks []string, retry bool, fn func(q *Request) error) error {
	if q == nil {
		return s.txLocks(ctx, nil, write, locks, retry, func(tx pgx.Tx) error { return fn(backgroundRequest(ctx, s.appOf(), tx)) })
	}
	return s.txLocks(ctx, scopeOf(q.person), write, locks, retry, func(tx pgx.Tx) error {
		q.tx = tx
		defer func() { q.tx = nil }()
		return fn(q)
	})
}

// txWrites: whether tx is a write transaction of the Store.
func txWrites(tx pgx.Tx) bool {
	v, ok := txLockStates.Load(tx)
	if !ok {
		return false
	}
	st := v.(*txLockState)
	st.mu.Lock()
	defer st.mu.Unlock()
	return st.write
}

// typedRows: the rows of a statement sql_builder.go assembled, each as T by column name (its db tags).
func typedRows[T any](q *Request, sql string, args []any) ([]T, error) {
	rs, err := q.tx.Query(q.ctx(), sql, args...)
	if err != nil {
		return nil, err
	}
	return pgx.CollectRows(rs, pgx.RowToStructByName[T])
}

// db: the typed queries in the request's transaction.
func (q *Request) db() *db.Queries { return db.New(q.tx) }

func exec(q *Request, sql string, args ...any) error {
	_, err := q.tx.Exec(q.ctx(), sql, args...)
	return err
}

// afterCommit runs fn once q's transaction has committed, in the caller's goroutine; never when it rolls back (a retried
// attempt's effects are dropped with it). The only way to an effect outside the database (a wake, a file, a cache).
func afterCommit(q *Request, fn func()) {
	onEnd(q.tx, func(committed bool) {
		if committed {
			fn()
		}
	})
}

// afterRollback runs fn once q's transaction has rolled back, in the caller's goroutine (cleanup of staged files,
// spans or in-memory state on abort or retry).
func afterRollback(q *Request, fn func()) {
	onEnd(q.tx, func(committed bool) {
		if !committed {
			fn()
		}
	})
}
